mapper.sql:
WHERE enabled = TRUE AND role_type <> 'archived'
AND role_type = #{role}
AND energy = #{energy}

    AND (
        english_name LIKE CONCAT('%', #{term}, '%') OR anime_title LIKE CONCAT('%', #{term}, '%')
        OR role_type LIKE CONCAT('%', #{term}, '%') OR tags LIKE CONCAT('%', #{term}, '%') OR energy LIKE CONCAT('%', #{term}, '%')
    )

WHERE r.user_id = #{userId}

    AND (
        c.english_name LIKE CONCAT('%', #{term}, '%') OR c.anime_title LIKE CONCAT('%', #{term}, '%')
        OR r.wish_topic LIKE CONCAT('%', #{term}, '%') OR r.message LIKE CONCAT('%', #{term}, '%')
    )

AND r.mood = #{mood}
AND r.fortune_score >= #{minScore}
AND r.draw_time >= #{start}
AND r.draw_time < DATE_ADD(#{end}, INTERVAL 1 DAY)
AND r.wish_id = #{wishId}

mapper.select:
SELECT DATE_FORMAT(draw_time, '%Y-%m-%d') AS day, COUNT(*) AS total, MAX(draw_type = 'DAILY') AS daily
FROM sekai_Draw_lots_record WHERE user_id = #{userId} AND draw_time >= #{start} AND draw_time < #{end}
GROUP BY DATE(draw_time) ORDER BY day
